CREATE EXTERNAL TABLE IF NOT EXISTS robo_advisor_tt.raw_fundamentals ( ticker string, sector string, industry string, marketcap double, trailingpe double, forwardpe double, beta double, dividendyield double, currency string, quotetype string ) PARTITIONED BY (ingestion_date string) ROW FORMAT SERDE 'org.apache.hadoop.hive.serde2.lazy.LazySimpleSerDe' WITH SERDEPROPERTIES ('field.delim' = ',', 'serialization.format' = ',') STORED AS TEXTFILE LOCATION 's3://mgmt59900-group1-robo-advisor-tt/raw/yfinance/fundamentals/' TBLPROPERTIES ('skip.header.line.count' = '1')